'use client';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { 
    ZoomIn, 
    ZoomOut, 
    RotateCcw, 
    Share2, 
    Download,
    Save,
    LayoutDashboard,
    Loader2
} from 'lucide-react';
import { 
    Tooltip, 
    TooltipContent, 
    TooltipProvider, 
    TooltipTrigger 
} from '@/components/ui/tooltip';
import Link from 'next/link';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils/cn';

interface TopToolbarProps {
    projectName: string;
    onProjectNameChange: (name: string) => void;
    zoomLevel: number;
    onZoomIn: () => void;
    onZoomOut: () => void;
    onZoomReset: () => void;
    isSaving?: boolean;
    lastUpdated?: string;
}

export function TopToolbar({
    projectName,
    onProjectNameChange,
    zoomLevel,
    onZoomIn,
    onZoomOut,
    onZoomReset,
    isSaving,
    lastUpdated
}: TopToolbarProps) {
    return (
        <header className="h-14 border-b bg-background flex items-center justify-between px-4 shrink-0 z-30">
            <div className="flex items-center gap-4 flex-1 min-w-0">
                <Link href="/dashboard" className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors mr-2">
                    <LayoutDashboard className="h-5 w-5" />
                </Link>

                <div className="flex flex-col min-w-0 max-w-md">
                    <Input
                        className="text-sm font-medium h-8 border-transparent hover:border-input focus:border-input px-2 transition-all bg-transparent truncate"
                        value={projectName}
                        onChange={(e) => onProjectNameChange(e.target.value)}
                        placeholder="Untitled Project"
                    />
                    {lastUpdated && (
                        <span className="text-[10px] text-muted-foreground px-2">
                            {isSaving ? (
                                <span className="flex items-center gap-1">
                                    <Loader2 className="h-2 w-2 animate-spin" /> Saving...
                                </span>
                            ) : (
                                `Last updated ${lastUpdated}`
                            )}
                        </span>
                    )}
                </div>
            </div>

            <div className="flex items-center gap-2">
                {/* Zoom Controls */}
                <div className="flex items-center gap-1 border rounded-md px-1 mr-4 bg-muted/30">
                    <TooltipProvider>
                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button variant="ghost" size="icon" onClick={onZoomOut} className="h-8 w-8">
                                    <ZoomOut className="h-4 w-4" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent>Zoom Out</TooltipContent>
                        </Tooltip>

                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button variant="ghost" size="sm" onClick={onZoomReset} className="h-8 text-[11px] min-w-[44px]">
                                    {(zoomLevel * 100).toFixed(0)}%
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent>Reset Zoom</TooltipContent>
                        </Tooltip>

                        <Tooltip>
                            <TooltipTrigger asChild>
                                <Button variant="ghost" size="icon" onClick={onZoomIn} className="h-8 w-8">
                                    <ZoomIn className="h-4 w-4" />
                                </Button>
                            </TooltipTrigger>
                            <TooltipContent>Zoom In</TooltipContent>
                        </Tooltip>
                    </TooltipProvider>
                </div>

                <div className="flex items-center gap-2 border-l pl-4">
                    <Button variant="outline" size="sm" className="h-8 gap-2">
                        <Share2 className="h-3.5 w-3.5" />
                        Share
                    </Button>
                    <Button variant="outline" size="sm" className="h-8 gap-2">
                        <Download className="h-3.5 w-3.5" />
                        Export
                    </Button>
                    <Button size="sm" className="h-8 gap-2">
                        <Save className="h-3.5 w-3.5" />
                        Publish
                    </Button>
                </div>
            </div>
        </header>
    );
}

'use client';

import { 
    Layers, 
    ChevronDown, 
    ChevronRight, 
    Plus, 
    MoreHorizontal,
    GripVertical,
    Layout,
    Type,
    Image as ImageIcon,
    FileText
} from 'lucide-react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils/cn';
import { 
    DropdownMenu, 
    DropdownMenuContent, 
    DropdownMenuItem, 
    DropdownMenuTrigger 
} from '@/components/ui/dropdown-menu';
import { ProjectContent } from '@/lib/types';

interface LayersSidebarProps {
    projectContent: ProjectContent;
    activeSectionId?: string;
    onSectionSelect: (sectionId: string) => void;
    onAddChapter: () => void;
}

export function LayersSidebar({
    projectContent,
    activeSectionId,
    onSectionSelect,
    onAddChapter
}: LayersSidebarProps) {
    const chapters = projectContent.chapters || [];

    return (
        <aside className="w-64 border-r bg-background flex flex-col h-full shrink-0 z-20 overflow-hidden">
            <div className="h-12 border-b flex items-center justify-between px-4 shrink-0">
                <div className="flex items-center gap-2 font-medium text-sm">
                    <Layers className="h-4 w-4 text-primary" />
                    Outline
                </div>
                <Button variant="ghost" size="icon" className="h-8 w-8" onClick={onAddChapter}>
                    <Plus className="h-4 w-4" />
                </Button>
            </div>

            <ScrollArea className="flex-1">
                <div className="p-2 space-y-1">
                    {chapters.length === 0 ? (
                        <div className="p-4 text-center text-xs text-muted-foreground italic">
                            No chapters added yet. Start by generating or adding a chapter.
                        </div>
                    ) : (
                        chapters.map((chapter, index) => (
                            <div key={chapter.id} className="space-y-0.5">
                                <div className="group flex items-center gap-1 px-2 py-1.5 rounded-md hover:bg-muted/50 transition-colors cursor-default">
                                    <ChevronDown className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                                    <div className="flex items-center gap-2 flex-1 min-w-0">
                                        <Layout className="h-3.5 w-3.5 text-primary shrink-0" />
                                        <span className="text-xs font-semibold truncate uppercase tracking-tight">
                                            {chapter.title || `Chapter ${index + 1}`}
                                        </span>
                                    </div>
                                    <DropdownMenu>
                                        <DropdownMenuTrigger asChild>
                                            <Button variant="ghost" size="icon" className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <MoreHorizontal className="h-3 w-3" />
                                            </Button>
                                        </DropdownMenuTrigger>
                                        <DropdownMenuContent align="end" className="w-40">
                                            <DropdownMenuItem className="text-xs">Rename</DropdownMenuItem>
                                            <DropdownMenuItem className="text-xs text-destructive">Delete</DropdownMenuItem>
                                        </DropdownMenuContent>
                                    </DropdownMenu>
                                </div>

                                <div className="ml-4 pl-1 border-l space-y-0.5">
                                    {(chapter.sections || []).map((section) => (
                                        <button
                                            key={section.id}
                                            onClick={() => onSectionSelect(section.id)}
                                            className={cn(
                                                "w-full flex items-center gap-2 px-2 py-1.5 rounded-md text-left text-xs transition-colors",
                                                activeSectionId === section.id 
                                                    ? "bg-primary/10 text-primary font-medium" 
                                                    : "hover:bg-muted/50 text-muted-foreground hover:text-foreground"
                                            )}
                                        >
                                            <FileText className="h-3 w-3 shrink-0" />
                                            <span className="truncate">{section.title}</span>
                                        </button>
                                    ))}
                                    <button className="w-full flex items-center gap-2 px-2 py-1.5 rounded-md text-xs text-muted-foreground hover:text-primary transition-colors hover:bg-primary/5">
                                        <Plus className="h-3 w-3 shrink-0" />
                                        <span>Add Section</span>
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </ScrollArea>
        </aside>
    );
}

'use client';

import { 
    Settings, 
    UploadCloud, 
    LayoutTemplate, 
    BookOpenCheck,
    MessageSquare,
    ChevronLeft,
    ChevronRight,
    Search,
    History
} from 'lucide-react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils/cn';
import { 
    Tooltip, 
    TooltipContent, 
    TooltipProvider, 
    TooltipTrigger 
} from '@/components/ui/tooltip';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import React from 'react';

interface Panel {
    key: string;
    title: string;
    icon: React.ReactNode;
    content: React.ReactNode;
}

interface InspectorSidebarProps {
    panels: Panel[];
    activePanelKey: string;
    onActivePanelChange: (key: string) => void;
    isChatOpen: boolean;
    onToggleChat: () => void;
}

export function InspectorSidebar({
    panels,
    activePanelKey,
    onActivePanelChange,
    isChatOpen,
    onToggleChat
}: InspectorSidebarProps) {
    return (
        <aside className="w-[340px] border-l bg-background flex flex-col h-full shrink-0 z-20 overflow-hidden">
            <div className="flex-1 flex flex-col min-h-0">
                <Tabs value={activePanelKey} onValueChange={onActivePanelChange} className="flex-1 flex flex-col h-full">
                    <div className="h-12 border-b flex items-center px-2 shrink-0 bg-muted/20">
                        <TabsList className="bg-transparent border-none w-full justify-start gap-1 p-0">
                            {panels.map((panel) => (
                                <TabsTrigger 
                                    key={panel.key} 
                                    value={panel.key}
                                    className="data-[state=active]:bg-background data-[state=active]:shadow-sm h-8 px-3 rounded-md text-xs transition-all"
                                >
                                    {panel.icon}
                                    <span className="sr-only">{panel.title}</span>
                                </TabsTrigger>
                            ))}
                        </TabsList>

                        <div className="ml-auto flex items-center gap-1 border-l pl-2">
                             <TooltipProvider>
                                <Tooltip>
                                    <TooltipTrigger asChild>
                                        <Button 
                                            variant={isChatOpen ? "secondary" : "ghost"} 
                                            size="icon" 
                                            className="h-8 w-8 relative"
                                            onClick={onToggleChat}
                                        >
                                            <MessageSquare className="h-4 w-4" />
                                            {isChatOpen && <span className="absolute top-1 right-1 w-2 h-2 bg-primary rounded-full" />}
                                        </Button>
                                    </TooltipTrigger>
                                    <TooltipContent>AI Chat</TooltipContent>
                                </Tooltip>
                             </TooltipProvider>
                        </div>
                    </div>

                    <div className="h-10 border-b flex items-center px-4 shrink-0 justify-between bg-background">
                         <h3 className="text-[11px] font-bold uppercase tracking-wider text-muted-foreground">
                            {panels.find(p => p.key === activePanelKey)?.title}
                         </h3>
                         <div className="flex items-center gap-1">
                            <Button variant="ghost" size="icon" className="h-6 w-6">
                                <History className="h-3 w-3" />
                            </Button>
                         </div>
                    </div>

                    <div className="flex-1 overflow-hidden relative">
                        {panels.map((panel) => (
                            <TabsContent 
                                key={panel.key} 
                                value={panel.key} 
                                className="h-full m-0 p-0 focus-visible:ring-0"
                            >
                                <ScrollArea className="h-full">
                                    <div className="p-4">
                                        {panel.content}
                                    </div>
                                </ScrollArea>
                            </TabsContent>
                        ))}
                    </div>
                </Tabs>
            </div>

            <div className="h-12 border-t p-2 flex items-center justify-between shrink-0 bg-muted/10">
                <div className="flex -space-x-2">
                    <div className="h-6 w-6 rounded-full bg-blue-500 border-2 border-background flex items-center justify-center text-[8px] text-white font-bold">JD</div>
                    <div className="h-6 w-6 rounded-full bg-green-500 border-2 border-background flex items-center justify-center text-[8px] text-white font-bold">AI</div>
                    <div className="h-6 w-6 rounded-full bg-muted border-2 border-background flex items-center justify-center text-[8px] text-muted-foreground">+</div>
                </div>
                <Badge variant="outline" className="text-[10px] h-5 font-normal border-green-500/50 text-green-600 bg-green-50/50">
                    Live
                </Badge>
            </div>
        </aside>
    );
}

