'use client';

import { useLocalization } from '@/context/LocalizationContext';
import { cn } from '@/lib/utils/cn';
import { 
    Settings, 
    BookOpenText, 
    Loader2
} from 'lucide-react';
import React, { Suspense, lazy, useState, useCallback } from 'react';
import { Button } from '../ui/button';
import { BuilderPageSkeleton } from '@/app/builder/loading';
import { OnboardingGuide } from '@/components/onboarding/OnboardingGuide';
import { useReportGenerator } from '@/hooks/report-mode/useReportGenerator';
import { ProjectChat } from './chat/ProjectChat';
import { ProjectProperties } from '@/lib/types';

// Layout Components
import { TopToolbar } from './layout/TopToolbar';
import { LayersSidebar } from './layout/LayersSidebar';
import { InspectorSidebar } from './layout/InspectorSidebar';

const ReportResults = lazy(() => import('./ReportResults'));

function ReportSkeleton() {
    return (
        <div className="flex h-full items-center justify-center">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
    );
}

function BottomNavBar({ activeView, setActiveView }: { activeView: 'generator' | 'result', setActiveView: (view: 'generator' | 'result') => void }) {
    return (
        <div className="fixed bottom-0 left-0 right-0 h-16 bg-background border-t p-2 flex items-center justify-around z-50 lg:hidden">
            <Button
                variant={activeView === 'generator' ? 'secondary' : 'ghost'}
                className={cn("flex flex-col items-center h-full w-full", activeView === 'generator' && "text-primary")}
                onClick={() => setActiveView('generator')}
            >
                <Settings className="h-5 w-5 mb-1" />
                <span className="text-xs">Setup</span>
            </Button>
            <Button
                variant={activeView === 'result' ? 'secondary' : 'ghost'}
                className={cn("flex flex-col items-center h-full w-full", activeView === 'result' && "text-primary")}
                onClick={() => setActiveView('result')}
            >
                <BookOpenText className="h-5 w-5 mb-1" />
                <span className="text-xs">Document</span>
            </Button>
        </div>
    );
}

export default function ReportModeGenerator({ initialProject }: { initialProject?: ProjectProperties | null }) {
    const {
        locale,
        isMobile,
        activeMobileView,
        setActiveMobileView,
        activePanelKey,
        setActivePanelKey,
        showOnboarding,
        setShowOnboarding,
        handleOnboardingComplete,
        project,
        isStoreInitialized,
        updateProjectName,
        updateProject,
        isSaving,
        panels,
        isChatOpen,
        setIsChatOpen,
        zoomLevel,
        setZoomLevel,
    } = useReportGenerator(initialProject);

    const [activeSectionId, setActiveSectionId] = useState<string | undefined>(undefined);

    const handleZoomIn = () => setZoomLevel(prev => Math.min(2, prev + 0.1));
    const handleZoomOut = () => setZoomLevel(prev => Math.max(0.5, prev - 0.1));
    const handleZoomReset = () => setZoomLevel(1);

    const handleSectionSelect = useCallback((sectionId: string) => {
        setActiveSectionId(sectionId);
        // Add smooth scroll to element logic if needed
        const element = document.getElementById(`section-${sectionId}`);
        if (element) {
            element.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }, []);

    const handleAddChapter = useCallback(() => {
        // Logic to add a chapter
        console.log('Add chapter requested');
    }, []);

    if (!isStoreInitialized || !project) {
        return <BuilderPageSkeleton />;
    }

    // --- Desktop Layout ---
    if (!isMobile) {
        return (
            <div className="flex flex-col h-screen overflow-hidden bg-muted/20" dir={locale === 'ar' ? 'rtl' : 'ltr'}>
                <OnboardingGuide isOpen={showOnboarding} onOpenChange={setShowOnboarding} onComplete={handleOnboardingComplete} />

                <TopToolbar 
                    projectName={project.name}
                    onProjectNameChange={updateProjectName}
                    zoomLevel={zoomLevel}
                    onZoomIn={handleZoomIn}
                    onZoomOut={handleZoomOut}
                    onZoomReset={handleZoomReset}
                    isSaving={isSaving}
                    lastUpdated={project.meta.updated ? new Date(project.meta.updated).toISOString() : undefined}
                />

                <div className="flex flex-1 min-h-0">
                    <LayersSidebar 
                        projectContent={project.content}
                        activeSectionId={activeSectionId}
                        onSectionSelect={handleSectionSelect}
                        onAddChapter={handleAddChapter}
                    />

                    <main className="flex-1 overflow-auto relative bg-muted/10 flex justify-center p-8">
                        <div 
                            className="transition-transform duration-200 origin-top"
                            style={{ transform: `scale(${zoomLevel})` }}
                        >
                            <Suspense fallback={<ReportSkeleton />}>
                                <ReportResults activePanelKey={activePanelKey} />
                            </Suspense>
                        </div>
                    </main>

                    <InspectorSidebar 
                        panels={panels}
                        activePanelKey={activePanelKey}
                        onActivePanelChange={setActivePanelKey}
                        isChatOpen={isChatOpen}
                        onToggleChat={() => setIsChatOpen(prev => !prev)}
                    />
                </div>

                <ProjectChat isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} />
            </div>
        );
    }

    // --- Mobile Layout (Legacy/Current) ---
    return (
        <div className="relative flex-grow flex flex-col min-h-screen bg-background" dir={locale === 'ar' ? 'rtl' : 'ltr'}>
            <OnboardingGuide isOpen={showOnboarding} onOpenChange={setShowOnboarding} onComplete={handleOnboardingComplete} />

            <div className="flex flex-col flex-grow p-4 pb-20">
                <div className="flex flex-col space-y-4 mb-4">
                    <Input
                        className="text-xl font-bold border-none px-0 focus-visible:ring-0 bg-transparent"
                        value={project.name}
                        onChange={(e) => updateProjectName(e.target.value)}
                        placeholder="Untitled Project"
                    />
                </div>

                <Suspense fallback={<ReportSkeleton />}>
                    <div className="flex-grow">
                        {activeMobileView === 'generator' ? (
                            <div className="space-y-4">
                                {panels.map(panel => (
                                    <div key={panel.key} className="border rounded-lg p-4 bg-card">
                                        <h3 className="text-sm font-semibold mb-3 flex items-center gap-2">
                                            {panel.icon}
                                            {panel.title}
                                        </h3>
                                        {panel.content}
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <ReportResults activePanelKey={activePanelKey} />
                        )}
                    </div>
                </Suspense>
            </div>

            <ProjectChat isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} />
            <BottomNavBar activeView={activeMobileView} setActiveView={setActiveMobileView} />
        </div>
    );
}

