  20   content: string;
  21   onChange: (markdown: string) => void;
  22   editorClassName?: string;
  23 }
  24 
  25 const MarkdownEditorComponent = ({ content, onChange, editorClassName }: MarkdownEditorProps) => {
  26   const { setActiveEditor } = useEditorStore();
  27   const bubbleMenuId = React.useId();
  28 
  29   const editor = useEditor({
  30     extensions: editorExtensions(bubbleMenuId),
  31     content: marked.parse(content) as string,
  32     onBlur: ({ editor }) => {
  33       const markdown = turndownService.turndown(editor.getHTML());
  34       onChange(markdown);
  35     },
  36     editorProps: {
  37       attributes: {
  38         class: cn('prose dark:prose-invert max-w-none focus:outline-none font-serif text-base prose-p:text-base prose-headings:font-headline prose-a:text-primary hover:prose-a:text-primary/80 prose-table:w-full prose-table:table-fixed prose-tr:border-b prose-th:text-left prose-th:p-2 prose-td:p-2', editorClassName),
  39       },
  40       handlePaste: (view, event, slice): boolean => {
  41         const text = event.clipboardData?.getData('text/plain');
  42         const html = event.clipboardData?.getData('text/html');
  43 
  44         if (html) {
  45             void handleHtmlPaste(editor!, html);
  46             return true;
  47         }
  48 
  49         if (text) {
  50           void handlePlainPaste(editor!, text);
  51           return true;
  52         }
  53         
  54         return false;
  55       },
  56     },
  57     immediatelyRender: false,
  58   });
  59 
  60   // Set the global editor instance when it's created and destroy it on unmount
  61   React.useEffect(() => {
  62     if (editor) {
  63       setActiveEditor(editor);
  64     }
  65     return () => {
  66       setActiveEditor(null);
  67       editor?.destroy();
  68     };
  69   }, [editor, setActiveEditor]);
  70 
  71   const handleWrapperClick = (event: React.MouseEvent<HTMLDivElement>) => {
  72     if (editor && event.target === event.currentTarget) {
  73       editor.chain().focus().run();
  74     }
  75   };
  76 
