import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils/cn';

interface Panel {
    key: string;
    title: string;
    icon: React.ReactNode;
    content: React.ReactNode;
}

interface TopToolbarProps {
    projectName: string;
    onProjectNameChange: (name: string) => void;
    zoomLevel: number;
    onZoomIn: () => void;
    onZoomOut: () => void;
    onZoomReset: () => void;
    isSaving?: boolean;
    lastUpdated?: string;
    navPanels: Panel[];
    activePanelKey: string;
    onActivePanelChange: (key: string) => void;
}

export function TopToolbar({
    projectName,
    onProjectNameChange,
    zoomLevel,
    onZoomIn,
    onZoomOut,
    onZoomReset,
    isSaving,
    lastUpdated,
    navPanels,
    activePanelKey,
    onActivePanelChange
}: TopToolbarProps) {
    return (
        <header className="h-14 border-b bg-background flex items-center justify-between px-4 shrink-0 z-30">
            <div className="flex items-center gap-4 flex-1 min-w-0">
                <Link href="/dashboard" className="flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors mr-2">
                    <LayoutDashboard className="h-5 w-5" />
                </Link>

                <div className="flex flex-col min-w-0 max-w-[180px]">
                    <Input
                        className="text-sm font-medium h-8 border-transparent hover:border-input focus:border-input px-2 transition-all bg-transparent truncate"
                        value={projectName}
                        onChange={(e) => onProjectNameChange(e.target.value)}
                        placeholder="Untitled Project"
                    />
                    {lastUpdated && (
                        <span className="text-[10px] text-muted-foreground px-2 truncate">
                            {isSaving ? (
                                <span className="flex items-center gap-1">
                                    <Loader2 className="h-2 w-2 animate-spin" /> Saving...
                                </span>
                            ) : (
                                `Last updated ${lastUpdated}`
                            )}
                        </span>
                    )}
                </div>
            </div>

            {/* Center Navigation */}
            <div className="flex items-center bg-muted/30 rounded-lg p-1 gap-1">
                {navPanels.map((panel) => (
                    <Button
                        key={panel.key}
                        variant={activePanelKey === panel.key ? "secondary" : "ghost"}
                        size="sm"
                        className={cn(
                            "h-8 px-3 gap-2 text-xs transition-all",
                            activePanelKey === panel.key ? "bg-background shadow-sm border" : "text-muted-foreground hover:text-foreground"
                        )}
                        onClick={() => onActivePanelChange(panel.key)}
                    >
                        {panel.icon}
                        {panel.title}
                    </Button>
                ))}
            </div>

            <div className="flex items-center gap-2 flex-1 justify-end">

